CREATE TABLE carrier_rate_cards(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL REFERENCES companies(id) ON DELETE CASCADE,carrier_service_id uuid NOT NULL,rate_name text NOT NULL,currency text NOT NULL DEFAULT 'PHP',origin_pattern text NOT NULL DEFAULT '*',destination_pattern text NOT NULL DEFAULT '*',minimum_weight_kg numeric(12,3) NOT NULL DEFAULT 0,maximum_weight_kg numeric(12,3),base_charge numeric(18,2) NOT NULL DEFAULT 0,per_kg_charge numeric(18,4) NOT NULL DEFAULT 0,volumetric_divisor numeric(12,2) NOT NULL DEFAULT 5000 CHECK(volumetric_divisor>0),fuel_surcharge_percent numeric(8,4) NOT NULL DEFAULT 0,remote_area_charge numeric(18,2) NOT NULL DEFAULT 0,handling_charge numeric(18,2) NOT NULL DEFAULT 0,insurance_percent numeric(8,4) NOT NULL DEFAULT 0,cod_percent numeric(8,4) NOT NULL DEFAULT 0,effective_from date NOT NULL,effective_to date,active boolean NOT NULL DEFAULT true,version integer NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now(),created_by uuid REFERENCES users(id),UNIQUE(company_id,carrier_service_id,rate_name,version),FOREIGN KEY(company_id,carrier_service_id) REFERENCES carrier_services(company_id,id),CHECK(effective_to IS NULL OR effective_to>=effective_from));
CREATE TABLE shipment_freight_costs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL REFERENCES companies(id) ON DELETE CASCADE,shipment_id uuid NOT NULL REFERENCES shipments(id) ON DELETE CASCADE,carrier_rate_card_id uuid REFERENCES carrier_rate_cards(id),currency text NOT NULL DEFAULT 'PHP',actual_weight_kg numeric(12,3) NOT NULL DEFAULT 0,volumetric_weight_kg numeric(12,3) NOT NULL DEFAULT 0,chargeable_weight_kg numeric(12,3) NOT NULL DEFAULT 0,base_amount numeric(18,2) NOT NULL DEFAULT 0,surcharge_amount numeric(18,2) NOT NULL DEFAULT 0,estimated_amount numeric(18,2) NOT NULL DEFAULT 0,actual_amount numeric(18,2),carrier_invoice_reference text,override_reason text,calculated_at timestamptz NOT NULL DEFAULT now(),calculated_by uuid REFERENCES users(id),actual_recorded_at timestamptz,actual_recorded_by uuid REFERENCES users(id),UNIQUE(company_id,shipment_id));
CREATE TABLE freight_cost_allocations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL REFERENCES companies(id) ON DELETE CASCADE,shipment_freight_cost_id uuid NOT NULL REFERENCES shipment_freight_costs(id) ON DELETE CASCADE,order_line_id uuid NOT NULL REFERENCES sales_order_lines(id) ON DELETE CASCADE,item_id uuid NOT NULL REFERENCES items(id),allocated_amount numeric(18,2) NOT NULL CHECK(allocated_amount>=0),allocation_basis text NOT NULL CHECK(allocation_basis IN('quantity','weight','value')),UNIQUE(shipment_freight_cost_id,order_line_id));
ALTER TABLE companies ADD COLUMN freight_variance_threshold_percent numeric(8,2) NOT NULL DEFAULT 10 CHECK(freight_variance_threshold_percent>=0);
CREATE VIEW carrier_freight_kpis WITH(security_invoker=true) AS SELECT f.company_id,o.warehouse_id,o.store_id,date_trunc('month',sh.dispatched_at)::date activity_month,f.currency,count(*) shipments,sum(f.estimated_amount) estimated_cost,sum(coalesce(f.actual_amount,f.estimated_amount)) actual_or_estimated_cost,sum(coalesce(f.actual_amount,0)-f.estimated_amount) recorded_variance,avg(coalesce(f.actual_amount,f.estimated_amount)) average_cost_per_shipment,sum(coalesce(f.actual_amount,f.estimated_amount))/nullif(sum(q.units),0) cost_per_unit FROM shipment_freight_costs f JOIN shipments sh ON sh.id=f.shipment_id JOIN sales_orders o ON o.id=sh.order_id JOIN LATERAL(SELECT sum(shipped_quantity) units FROM sales_order_lines WHERE order_id=o.id)q ON true GROUP BY f.company_id,o.warehouse_id,o.store_id,date_trunc('month',sh.dispatched_at)::date,f.currency;
ALTER TABLE carrier_rate_cards ENABLE ROW LEVEL SECURITY;ALTER TABLE carrier_rate_cards FORCE ROW LEVEL SECURITY;ALTER TABLE shipment_freight_costs ENABLE ROW LEVEL SECURITY;ALTER TABLE shipment_freight_costs FORCE ROW LEVEL SECURITY;ALTER TABLE freight_cost_allocations ENABLE ROW LEVEL SECURITY;ALTER TABLE freight_cost_allocations FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_carrier_rate_cards ON carrier_rate_cards USING(company_id=nullif(current_setting('app.company_id',true),'')::uuid) WITH CHECK(company_id=nullif(current_setting('app.company_id',true),'')::uuid);CREATE POLICY tenant_shipment_freight_costs ON shipment_freight_costs USING(company_id=nullif(current_setting('app.company_id',true),'')::uuid) WITH CHECK(company_id=nullif(current_setting('app.company_id',true),'')::uuid);CREATE POLICY tenant_freight_cost_allocations ON freight_cost_allocations USING(company_id=nullif(current_setting('app.company_id',true),'')::uuid) WITH CHECK(company_id=nullif(current_setting('app.company_id',true),'')::uuid);
GRANT SELECT,INSERT,UPDATE,DELETE ON carrier_rate_cards,shipment_freight_costs,freight_cost_allocations TO stockflow_app;GRANT SELECT ON carrier_freight_kpis TO stockflow_app;
CREATE INDEX carrier_rate_cards_effective_idx ON carrier_rate_cards(company_id,carrier_service_id,effective_from,effective_to);CREATE INDEX shipment_freight_costs_variance_idx ON shipment_freight_costs(company_id,actual_recorded_at);
